import json
n=30
grid=[[0]*n for _ in range(n)]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22,29]
for ti,r0 in enumerate(starts):
  for tj,c0 in enumerate(starts):
    col=colors[ti][tj] if ti<4 and tj<4 else None
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<n and c<n:
          # border 4; interior 3x3 pattern
          grid[r][c]=4 if dr in (0,4) or dc in (0,4) else col
# Overlay 3 rectangle perimeter, only into separator zeros
for r in [3,17]:
  for c in range(3,25):
    if grid[r][c]==0: grid[r][c]=3
for c in [3,24]:
  for r in range(3,18):
    if grid[r][c]==0: grid[r][c]=3
# Overlay 8 rectangle perimeter
for r in [10,24]:
  for c in range(10,18):
    if grid[r][c]==0: grid[r][c]=8
for c in [10,17]:
  for r in range(10,25):
    if grid[r][c]==0: grid[r][c]=8
print(json.dumps(grid))

# Rebuild the base grid and add connectors with the full colored-core thickness.
grid=[[0]*30 for _ in range(30)]
starts=[1,8,15,22,29]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for ti,r0 in enumerate(starts):
  for tj,c0 in enumerate(starts):
    col=colors[ti][tj] if ti<4 and tj<4 else None
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<30 and c<30: grid[r][c]=4 if dr in (0,4) or dc in (0,4) else col
# 3-colored rectangular pattern: rows 0,2 and columns 0,3
for ti in [0,2]:
  rows=range(starts[ti]+1,starts[ti]+4)
  for tj in range(3):
    for r in rows:
      for c in range(starts[tj]+5,starts[tj+1]):
        grid[r][c]=3
for tj in [0,3]:
  cols=range(starts[tj]+1,starts[tj]+4)
  for ti in range(2):
    for r in range(starts[ti]+5,starts[ti+1]):
      for c in cols: grid[r][c]=3
# 8-colored rectangle: rows 1,3 and columns 1,2
for ti in [1,3]:
  rows=range(starts[ti]+1,starts[ti]+4)
  for r in rows:
    for c in range(starts[1]+5,starts[2]): grid[r][c]=8
for tj in [1,2]:
  cols=range(starts[tj]+1,starts[tj]+4)
  for ti in [1,2]:
    for r in range(starts[ti]+5,starts[ti+1]):
      for c in cols: grid[r][c]=8
print(json.dumps(grid))
